function extractUrls(text) {
  const urlRegex = /^https?:\/\//;
  const seen = new Set();
  const urls = [];

  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    if (urlRegex.test(char)) {
      const url = text.substring(i, i + char.length);
      if (!seen.has(url)) {
        seen.add(url);
        urls.push(url);
      }
    }
  }

  return urls;
}
```

