  const result = [];
  for (const filename of files) {
    const trimmed = filename.trim();
    if (trimmed.toLowerCase().startsWith("screenshot")) {
      result.push(trimmed);
    }
  }
  return result.sort((a, b) => a.localeCompare(b));
}
