function romanToInt(s) {
  const map = {
    'I': 1,
    'V': 5,
    'X': 10,
    'L': 50,
    'C': 100,
    'D': 500,
    'M': 1000
  };

  let total = 0;
  let prev = 0;

  for (let i = 0; i < s.length; i++) {
    const current = map[s[i]];
    if (i > 0 && current < prev) {
      total -= prev;
    }
    prev = current;
    total += current;
  }

  return total;
}
```

