function twoSum(nums, target) {
  const map = new Map();
  map.set(0, -1); // Initialize with a sentinel value

  for (let i = 0; i < nums.length; i++) {
    const diff = target - nums[i];
    if (map.has(diff)) {
      const index = map.get(diff);
      return [index, i];
    }
    map.set(nums[i], i);
  }
  return [];
}
